            forcedStyle,
            itemTmp,

            tmpLevel,
            lg,

            tmp, tmpNum,
            val, cellCls,
            tmpCalculado,

            defaultMode = Store.renderMode === "default",

            labelsX = [],

            listeners = {},
            drillEnabled = false,

            cell, cellBGColor,

            CSSUtils = new GridHTML.view.CSSUtils(DashletSpec, Store, null),

            dimensionStyle = CSSUtils.getDimensionStyle(),
            horizontalSeparator = CSSUtils.getHorizontalSeparator(),
            verticalSeparator = CSSUtils.getVerticalSeparator(),
